 const expand=value=>{expanded=value;root.classList.toggle('pa-expanded',value);document.documentElement.classList.toggle('pa-game-expanded',value);ui.fullscreen.setAttribute('aria-pressed',String(value));ui.fullscreen.textContent=t(value?'Ekranı kiçilt':'Tam ekran');};
 const exitExpanded=()=>{expand(false);pause();if(document.fullscreenElement===root)document.exitFullscreen().catch(()=>{});};
 const fullscreenChanged=()=>{if(document.fullscreenElement===root)nativeFullscreen=true;else if(nativeFullscreen){nativeFullscreen=false;expand(false);pause();}};ui.fullscreen.onclick=()=>{if(expanded){exitExpanded();return;}expand(true);root.requestFullscreen?.().catch(()=>{});};document.addEventListener('fullscreenchange',fullscreenChanged);
 const changeCamera=value=>{cameraStyle=value==='pitch'?'pitch':'broadcast';get('camera-mode').value=cameraStyle;stats();if(!embedded)try{localStorage.setItem('ssl.fan.penalty.camera.v1',cameraStyle);}catch{}announce(t(cameraStyle==='pitch'?'Meydan kamerası':'TV kamerası'));};get('camera-mode').onchange=()=>changeCamera(get('camera-mode').value);ui.camera.onclick=()=>changeCamera(cameraStyle==='pitch'?'broadcast':'pitch');
 const installInput=()=>{
  const canvas=view.canvas;canvas.tabIndex=0;canvas.setAttribute('aria-label',t('Topdan qapıya doğru sürüşdür')+'. '+t('Oxlarla nişan al, boşluq düyməsi ilə vur.')+' '+t('Ox düymələri ilə atıl. S ilə mərkəzi qoru.'));
  canvas.addEventListener('pointerdown',event=>{if(!event.isPrimary||event.button!==0)return;if(keeperAllowed()){event.preventDefault();canvas.setPointerCapture(event.pointerId);drag={id:event.pointerId,kind:'keeper'};return;}if(!inputAllowed())return;const ball=view.ballScreen(),rect=canvas.getBoundingClientRect();if(Math.hypot(event.clientX-ball.x,event.clientY-ball.y)>Math.max(78,rect.height*.17))return;event.preventDefault();canvas.focus({preventScroll:true});canvas.setPointerCapture(event.pointerId);drag={id:event.pointerId,points:[{x:event.clientX,y:event.clientY,t:performance.now()}]};});
  canvas.addEventListener('pointermove',event=>{if(!drag||event.pointerId!==drag.id||!inputAllowed())return;event.preventDefault();drag.points.push({x:event.clientX,y:event.clientY,t:performance.now()});if(drag.points.length>90)drag.points.splice(1,1);aim=view.aimAt(event.clientX,event.clientY);ui.power.value=gestureShot(drag.points,canvas.getBoundingClientRect())?.power||.35;});
  canvas.addEventListener('pointerup',event=>{if(!drag||event.pointerId!==drag.id)return;if(drag.kind==='keeper'){drag=null;if(canvas.hasPointerCapture(event.pointerId))canvas.releasePointerCapture(event.pointerId);commitKeeper(view.aimAt(event.clientX,event.clientY));return;}const points=drag.points;points.push({x:event.clientX,y:event.clientY,t:performance.now()});drag=null;if(canvas.hasPointerCapture(event.pointerId))canvas.releasePointerCapture(event.pointerId);if(!inputAllowed())return;const gesture=gestureShot(points,canvas.getBoundingClientRect());if(gesture){aim=view.aimAt(event.clientX,event.clientY);fire(aim,gesture.power,gesture.spin);}});
  for(const name of ['pointercancel','lostpointercapture'])canvas.addEventListener(name,()=>{drag=null;});
  canvas.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();if(expanded)exitExpanded();else phase==='paused'?resume():pause();return;}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' ','Enter'].includes(event.key)&&phase!=='menu')event.preventDefault();if(keeperAllowed()){const keys={ArrowLeft:{x:-1.5,y:1},ArrowRight:{x:1.5,y:1},ArrowUp:{x:0,y:1.65},ArrowDown:{x:0,y:.35},s:{x:0,y:1},S:{x:0,y:1},q:{x:-1.5,y:1.6},e:{x:1.5,y:1.6},z:{x:-1.5,y:.35},c:{x:1.5,y:.35}};if(keys[event.key]){event.preventDefault();commitKeeper(keys[event.key]);}return;}if(!inputAllowed())return;if([' ','Enter'].includes(event.key))fire();else if(event.key.startsWith('Arrow')){aim.x=clamp(aim.x+({ArrowLeft:-.16,ArrowRight:.16}[event.key]||0),-3,3);aim.y=clamp(aim.y+({ArrowUp:.13,ArrowDown:-.13}[event.key]||0),.12,2.8);}});
 };
 const tick=now=>{
  if(destroyed)return;frameId=requestAnimationFrame(tick);const delta=Math.min(.25,Math.max(0,(now-lastTime)/1000||0));lastTime=now;if(!view||phase==='paused'||document.hidden)return;idle+=delta;
  if(!adsPaused){const old=adIndex;adTime+=delta;if(sponsors.length&&(Math.floor(adTime/6)+adOffset)%sponsors.length!==old)rotateSponsor();}
  if(phase==='intro'){introTime+=delta;if(introTime>=(reducedMotion?.35:1.1))ready();}
  if(phase==='defend'){runUp+=delta;get('countdown').textContent=String(Math.max(1,Math.ceil(1.5-runUp)));if(runUp>=1.5)rivalKick();}
  if(phase==='runup'){runUp+=delta;if(runUp>=.7&&pendingKick){const q=pendingKick;launchKick(q.target,q.power,q.spin,false);}}
  if(phase==='flight'&&shot){const timeScale=turn==='away'&&!shot.result?{easy:.38,normal:.5,hard:.7}[difficulty]:1,before=shot.result;accumulator+=delta*timeScale;while(accumulator>=PHYSICS_STEP){stepPenaltyShot(shot);accumulator-=PHYSICS_STEP;}if(!before&&shot.result){updateKeeperPad();tone(shot.result);vibrate(shot.result==='goal'?[25,35,50]:shot.result==='save'?25:12);}if(shot.result&&shot.t-shot.resolvedAt>.68)finish();}
  if(phase==='result'&&shot&&shot.t<2.5){accumulator+=delta;while(accumulator>=PHYSICS_STEP){stepPenaltyShot(shot);accumulator-=PHYSICS_STEP;}}
  if(phase==='replay'&&shot){replayTime+=delta*.45;if(replayTime>=shot.history.at(-1).t+.3){setPhase('result');ui.hint.textContent='';}}
  const replayFrame=phase==='replay'?shot.history.reduce((frame,next)=>next.t<=replayTime?next:frame,shot.history[0]):null;
  view.render({shot,idle,replay:phase==='replay',replayFrame,aim,aiming:inputAllowed()&&!!drag,phase,delta,sponsorIndex:adIndex,defending:turn==='away',keeperTarget:keeperAim,reducedMotion,cameraStyle,runUp,introTime,trophy:trophyWon()});
 };
 const beginRound=()=>{const rival=club(mode==='league'?leagueOpponent(league):cupOpponent(cup));if(!rival)return;clubs={...clubs,away:rival};duel=createDuel(c.duelRounds);ready();};
 const reset=(resumeSaved=false)=>{goals=shots=saves=hitChain=0;difficulty=get('difficulty').value;mode=get('mode').value;duel=createDuel(c.duelRounds);turn='home';clubs=chooseArenaClubs(data,get('home-team').value,get('away-team').value);cup=null;league=null;if(mode==='league'){const saved=resumeSaved?readLeague():null;league=saved?.league||createArenaLeague(clubs.teams,clubs.home.id,clubs.away.id,randomSeed());if(saved){goals=saved.stats.goals;shots=saved.stats.shots;saves=saved.stats.saves;}saveLeague();}else cup=createArenaCup(clubs.teams,clubs.home.id,clubs.away.id,randomSeed());beginRound();};
 const unavailable=()=>{if(destroyed)return;cancelAnimationFrame(frameId);view?.destroy();view=null;host.dataset.renderer='unavailable';shot=null;cup=league=null;turn='home';duel=createDuel(c.duelRounds);setPhase('menu');ui['3d-error'].hidden=false;syncClubs();announce(t('3D oyun açılmadı'));};
 const launchGame=async(resumeSaved=false)=>{
  if(loading||destroyed||!available())return;loading=true;ui.start.disabled=true;ui.clubs.disabled=true;ui.start.textContent=t('Yüklənir…');ui['3d-error'].hidden=true;
  try{runtime=await import(new URL('./penalty-runtime.js?v=20261021league3d',import.meta.url).href);if(destroyed)return;view=runtime.createPenaltyView(host,{sponsors,onContextLost:unavailable});installInput();reset(resumeSaved);introTime=0;setPhase('intro');stats();if(!expanded&&matchMedia('(max-width:760px)').matches)root.scrollIntoView({block:'center',behavior:'instant'});lastTime=performance.now();cancelAnimationFrame(frameId);frameId=requestAnimationFrame(tick);
  }catch(error){unavailable();if(error.message!=='ARENA_3D_UNAVAILABLE')console.error('Penalty arena load failed:',error);}
  finally{loading=false;ui.start.disabled=!available();ui.clubs.disabled=false;ui.start.textContent=t('Oyuna başla');}
 };
 ui.start.onclick=()=>launchGame(false);get('retry').onclick=()=>launchGame(mode==='league');ui['resume-league'].onclick=()=>{get('mode').value='league';mode='league';launchGame(true);};
 ui.next.onclick=()=>{if(!status().winner){ready();return;}if(mode==='league'?!league.complete:!cup.eliminated&&!cup.champion)beginRound();else reset();};
 if(ui.replay)ui.replay.onclick=()=>{if(phase!=='result'||!shot?.history.length)return;replayTime=0;ui.celebration.hidden=true;setPhase('replay');ui.hint.textContent=t('Təkrar');};
 ui.pause.onclick=pause;get('resume').onclick=resume;ui.reset.onclick=()=>reset();ui.clubs.onclick=()=>{view?.destroy();view=null;cancelAnimationFrame(frameId);shot=null;pendingKick=null;cup=league=null;duel=createDuel(c.duelRounds);turn='home';goals=shots=saves=hitChain=0;ui.celebration.hidden=true;setPhase('menu');syncClubs();ui.start.focus({preventScroll:true});};
 if(ui.sound)ui.sound.onclick=async()=>{soundOn=!soundOn;if(soundOn){try{await initAudio();}catch{soundOn=false;}}audioMode();ui.sound.setAttribute('aria-pressed',String(soundOn));};
 if(typeof navigator!=='undefined'&&typeof navigator.vibrate==='function'&&matchMedia('(pointer: coarse)').matches){ui.vibration.hidden=false;ui.vibration.onclick=()=>{vibrationOn=!vibrationOn;ui.vibration.setAttribute('aria-pressed',String(vibrationOn));if(vibrationOn)vibrate(12);else try{navigator.vibrate(0);}catch{}};}
 assist.addEventListener('click',event=>{const button=event.target.closest('[data-pa-aim]');if(button){const [x,y]=button.dataset.paAim.split(',').map(Number);aim={x,y};assist.querySelectorAll('[data-pa-aim]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));if(inputAllowed())announce(button.textContent);}if(event.target.closest('#pa-shoot'))fire();});
 const hidden=()=>{if(document.hidden)pause();};document.addEventListener('visibilitychange',hidden);const visibility=new IntersectionObserver(entries=>{if(entries[0]&&!entries[0].isIntersecting&&!expanded)pause();},{threshold:0});visibility.observe(stage);
